    private static string DtoFile(CrudNames n, string name, string summary, string? remark)
    {
        List<(string Name, string Type)> fields = DtoFields(n);
        string parameters = string.Join(",\n", fields.Select(f => $"    {f.Type} {f.Name}"));
        string projection = string.Join(",\n", fields.Select(f => $"            x.{f.Name}"));
        string remarks = remark is null ? string.Empty : $"\n/// <remarks>{remark}</remarks>";

        return $$"""
            {{Header}}
            using System.Linq.Expressions;
            using {{n.Model.Namespace}};

            namespace {{n.DtosNamespace}};

            /// <summary>{{summary}}</summary>{{remarks}}
            public sealed record {{name}}(
            {{parameters}})
            {
                /// <summary>Sorguda doğrudan SQL'e çevrilen eşleme (yalnızca gereken sütunlar okunur).</summary>
                public static Expression<Func<{{n.Entity}}, {{name}}>> Projection { get; } =
                    x => new {{name}}(
            {{projection}});
            }

            """;
    }

    private static List<(string Name, string Type)> DtoFields(CrudNames n)
    {
        var fields = new List<(string Name, string Type)> { ("Id", n.IdType) };
        fields.AddRange(n.Model.ScalarProperties.Where(p => p.Name != "Id").Select(p => (p.Name, p.Type)));
        if (n.Model.IsAudited)
        {
            fields.Add(("CreatedAt", "DateTimeOffset"));
            fields.Add(("UpdatedAt", "DateTimeOffset?"));
        }

        return fields;
    }

