    public static string Validator(CrudNames n, string operation, IReadOnlyList<MethodParameter> parameters)
    {
        var rules = new List<string>();
        if (operation == "Update" && n.IdType == "Guid")
            rules.Add("RuleFor(x => x.Id).NotEmpty();");

        foreach (MethodParameter parameter in parameters)
        {
            string? max = n.Model.MaxLengthConstant(parameter.Name);
            var chain = new List<string>();

            if (parameter.IsString && !parameter.IsNullable)
                chain.Add("NotEmpty()");
            if (parameter.IsString && max is not null)
                chain.Add($"MaximumLength({n.Entity}.{max})");
            if (parameter.BareType == "Guid" && !parameter.IsNullable)
                chain.Add("NotEmpty()");
            if (n.Model.Properties.FirstOrDefault(p => p.Name == parameter.Name) is { Kind: PropertyKind.Enum })
                chain.Add("IsInEnum()");

            if (chain.Count > 0)
                rules.Add($"RuleFor(x => x.{parameter.Name}).{string.Join('.', chain)};");
            else if (parameter.IsString)
                rules.Add($"// TODO(can-gen): {parameter.Name} için uzunluk sınırı yok; entity'ye {parameter.Name}MaxLength sabiti ekle ya da: RuleFor(x => x.{parameter.Name}).MaximumLength(...);");
        }

        rules.Add("// TODO(can-gen): Diğer doğrulama kurallarını ekle (aralık, biçim ...). İş kuralları (veritabanı gerektirenler) Rules'ta.");
        string body = string.Join("\n", rules.Select(r => "        " + r));

        return $$"""
            {{Header}}
            using FluentValidation;
            using {{n.Model.Namespace}};

            namespace {{n.FeatureNamespace}}.Commands.{{operation}};

            public sealed class {{operation}}{{n.Entity}}CommandValidator : AbstractValidator<{{operation}}{{n.Entity}}Command>
            {
                public {{operation}}{{n.Entity}}CommandValidator()
                {
            {{body}}
                }
            }

            """;
    }

