        public sealed record Get{{n.Entity}}ByIdQuery({{n.IdType}} Id) : IRequest<Result<{{n.Entity}}Dto>>, ISecuredRequest
        {
            public IReadOnlyCollection<string> Permissions => [{{n.Entity}}Permissions.Read];
