        public sealed class Get{{n.Entity}}ByIdQueryHandler : IRequestHandler<Get{{n.Entity}}ByIdQuery, Result<{{n.Entity}}Dto>>
        {
            private readonly IRepository<{{n.Entity}}, {{n.IdType}}> {{n.Repository}};

            public Get{{n.Entity}}ByIdQueryHandler(IRepository<{{n.Entity}}, {{n.IdType}}> {{n.Repository[1..]}}) => {{n.Repository}} = {{n.Repository[1..]}};

            public async Task<Result<{{n.Entity}}Dto>> Handle(Get{{n.Entity}}ByIdQuery request, CancellationToken cancellationToken)
            {
                {{n.Entity}}Dto? dto = await {{n.Repository}}
