    public static string GetListQuery(CrudNames n)
    {
        List<string> fields = n.Model.ScalarProperties.Where(p => p.Name != "Id").Select(p => $"x => x.{p.Name}").ToList();
        if (n.Model.IsAudited)
            fields.Add("x => x.CreatedAt");

        string allow = fields.Count == 0 ? string.Empty : $"\n        .Allow({string.Join(", ", fields)})";
        string sort = n.Model.IsAudited ? "q => q.OrderByDescending(x => x.CreatedAt)" : "q => q.OrderBy(x => x.Id)";

        return $$"""
            {{Header}}
            using Can.Core.Application;
            using Can.Core.Domain.Results;
            using Can.Core.Mediator;
            using Can.Core.Persistence.Dynamic;
            using Can.Core.Persistence.Paging;
            using Can.Core.Persistence.Repositories;
            using FluentValidation;
            using {{n.Root}}.Application.Common;
            using {{n.Model.Namespace}};
            using {{n.ConstantsNamespace}};
            using {{n.DtosNamespace}};

            namespace {{n.FeatureNamespace}}.Queries.GetList;

            /// <summary>
            /// {{n.Words}} listesi: sayfa numaralı (toplam sayıyla) ve istemcinin dinamik filtre/sıralaması
            /// (<see cref="DynamicQuery"/>; yalnızca izin verilen alanlarla).
            /// </summary>
            public sealed record Get{{n.Plural}}Query(PageRequest Page, DynamicQuery? Query = null)
                : IRequest<Result<IPaginate<{{n.Entity}}ListItemDto>>>, ISecuredRequest
            {
                public IReadOnlyCollection<string> Permissions => [{{n.Entity}}Permissions.Read];
            }

            public sealed class Get{{n.Plural}}QueryValidator : AbstractValidator<Get{{n.Plural}}Query>
            {
                public Get{{n.Plural}}QueryValidator() => RuleFor(x => x.Page).ValidPage();
            }

            public sealed class Get{{n.Plural}}QueryHandler : IRequestHandler<Get{{n.Plural}}Query, Result<IPaginate<{{n.Entity}}ListItemDto>>>
            {
                /// <summary>İstemcinin filtreleyip sıralayabileceği alanlar. TODO(can-gen): Gerekmeyenleri çıkar.</summary>
                private static readonly DynamicQueryFields<{{n.Entity}}> Fields = new DynamicQueryFields<{{n.Entity}}>(){{allow}};

                private readonly IRepository<{{n.Entity}}, {{n.IdType}}> {{n.Repository}};

                public Get{{n.Plural}}QueryHandler(IRepository<{{n.Entity}}, {{n.IdType}}> {{n.Repository[1..]}}) => {{n.Repository}} = {{n.Repository[1..]}};

                public async Task<Result<IPaginate<{{n.Entity}}ListItemDto>>> Handle(Get{{n.Plural}}Query request, CancellationToken cancellationToken)
                {
                    Result<IQueryable<{{n.Entity}}>> query = DynamicSearch.Apply({{n.Repository}}.Query(enableTracking: false), request.Query, Fields, {{sort}});
                    if (query.IsFailure)
                        return query.Errors;

                    return Result.Ok(await query.Value
                        .Select({{n.Entity}}ListItemDto.Projection)
                        .ToPaginateAsync(request.Page.Index, request.Page.Size, cancellationToken: cancellationToken));
                }
            }

            """;
    }

