    public static string Configuration(CrudNames n)
    {
        var lines = new List<string>();
        foreach (EntityProperty property in n.Model.Properties.Where(p => p.Name != "Id"))
        {
            string? max = n.Model.MaxLengthConstant(property.Name);
            switch (property.Kind)
            {
                case PropertyKind.Scalar when property.IsString:
                    string required = property.IsNullable ? string.Empty : ".IsRequired()";
                    lines.Add(max is not null
                        ? $"builder.Property(x => x.{property.Name}).HasMaxLength({n.Entity}.{max}){required};"
                        : $"builder.Property(x => x.{property.Name}){required}; // TODO(can-gen): Uzunluk sınırı ver: .HasMaxLength(...)");
                    break;
                case PropertyKind.Scalar when property.BareType is "decimal" or "Decimal":
                    lines.Add($"builder.Property(x => x.{property.Name}).HasPrecision(18, 2); // TODO(can-gen): Hassasiyeti kontrol et.");
                    break;
                case PropertyKind.Enum:
                    lines.Add($"builder.Property(x => x.{property.Name}).HasConversion<string>().HasMaxLength(32);");
                    break;
                case PropertyKind.Collection:
                    lines.Add($"// TODO(can-gen): {property.Name} koleksiyonunu eşle: builder.HasMany(x => x.{property.Name}).WithOne().HasForeignKey(\"{n.Entity}Id\");");
                    break;
                case PropertyKind.Complex:
                    lines.Add($"// TODO(can-gen): {property.Name} ({property.BareType}) için eşleme yaz: value object ise builder.OwnsOne(x => x.{property.Name}), entity ise ilişki (HasOne).");
                    break;
            }
        }

        lines.Add("// TODO(can-gen): Index ve ilişkileri ekle, ör. builder.HasIndex(x => x.Name).IsUnique();");
        string body = string.Join("\n", lines.Select(l => "        " + l));

        return $$"""
            {{Header}}
            using Microsoft.EntityFrameworkCore;
            using Microsoft.EntityFrameworkCore.Metadata.Builders;
            using {{n.Model.Namespace}};

            namespace {{n.Root}}.Persistence.Configurations;

            internal sealed class {{n.Entity}}Configuration : IEntityTypeConfiguration<{{n.Entity}}>
            {
                public void Configure(EntityTypeBuilder<{{n.Entity}}> builder)
                {
                    builder.ToTable("{{n.Plural}}", Schemas.App);

            {{body}}
                }
            }

            """;
    }

