    public static string Endpoints(CrudNames n)
    {
        string createFields = Parameters(n.CreateParameters);
        string updateFields = Parameters(n.UpdateParameters);
        string createArgs = Arguments(n.CreateParameters, "body");
        string updateArgs = n.UpdateParameters.Count == 0 ? string.Empty : ", " + Arguments(n.UpdateParameters, "body");
        string summaryWords = n.Words.ToLowerInvariant();

        return $$"""
            {{Header}}
            using Can.Core.Mediator;
            using Can.Core.Persistence.Dynamic;
            using Can.Core.WebApi;
            using Can.Core.WebApi.Versioning;
            using {{n.Root}}.Application.Common;
            using {{n.FeatureNamespace}}.Commands.Create;
            using {{n.FeatureNamespace}}.Commands.Delete;
            using {{n.FeatureNamespace}}.Commands.Update;
            using {{n.FeatureNamespace}}.Queries.GetById;
            using {{n.FeatureNamespace}}.Queries.GetList;
            using {{n.Model.Namespace}};

            namespace {{n.Root}}.WebApi.Endpoints;

            /// <summary>
            /// <c>/api/v1/{{n.Route}}</c>. Yetki handler'larda (<c>ISecuredRequest</c>, {{n.Entity}}Permissions) denetlenir;
            /// uçlar ayrıca giriş ister.
            /// </summary>
            internal static class {{n.Entity}}Endpoints
            {
                public sealed record Create{{n.Entity}}Request({{createFields}});

                public sealed record Update{{n.Entity}}Request({{updateFields}});

                /// <summary>Liste POST ile sorgulanır: gövdede sayfa ve dinamik filtre/sıralama.</summary>
                public sealed record Search{{n.Plural}}Request(int Index = 0, int Size = 20, DynamicQuery? Query = null);

                public static IEndpointRouteBuilder Map{{n.Entity}}Endpoints(this IEndpointRouteBuilder app)
                {
                    RouteGroupBuilder group = app.MapApiVersion(1).MapGroup("/{{n.Route}}").WithTags("{{n.Plural}}").RequireAuthorization();

                    group.MapGet("/{{n.RouteId}}", ({{n.IdType}} id, ISender sender, CancellationToken ct) =>
                            sender.Send(new Get{{n.Entity}}ByIdQuery(id), ct).ToHttpResult())
                        .WithSummary("{{n.Words}} ayrıntısı.");

                    group.MapPost("/search", (Search{{n.Plural}}Request body, ISender sender, CancellationToken ct) =>
                            sender.Send(new Get{{n.Plural}}Query(new PageRequest(body.Index, body.Size), body.Query), ct).ToHttpResult())
                        .WithSummary("{{n.Words}} listesi: dinamik filtre/sıralama + sayfa numarası.");

                    group.MapPost("/", (Create{{n.Entity}}Request body, ISender sender, CancellationToken ct) =>
                            sender.Send(new Create{{n.Entity}}Command({{createArgs}}), ct)
                                .ToHttpResult(id => TypedResults.Created($"/api/v1/{{n.Route}}/{id}", new { id })))
                        .WithSummary("Yeni {{summaryWords}} oluşturur.");

                    group.MapPut("/{{n.RouteId}}", ({{n.IdType}} id, Update{{n.Entity}}Request body, ISender sender, CancellationToken ct) =>
                            sender.Send(new Update{{n.Entity}}Command(id{{updateArgs}}), ct).ToHttpResult())
                        .WithSummary("{{n.Words}} kaydını günceller.");

                    group.MapDelete("/{{n.RouteId}}", ({{n.IdType}} id, ISender sender, CancellationToken ct) =>
                            sender.Send(new Delete{{n.Entity}}Command(id), ct).ToHttpResult())
                        .WithSummary("{{n.Words}} kaydını siler.");

                    return app;
                }
            }

            """;
    }

    // ------------------------------------------------------------------ yardımcılar

    private static string Parameters(IReadOnlyList<MethodParameter> parameters) =>
        string.Join(", ", parameters.Select(p => $"{p.Type} {p.Name}"));

    private static string Arguments(IReadOnlyList<MethodParameter> parameters, string source) =>
        string.Join(", ", parameters.Select(p => $"{source}.{p.Name}"));
}
